"use client";

import * as React from "react";

export interface AnnualMatrixPricingTier {
  name: string;
  price: string;
  period?: string;
  highlight?: boolean;
  cta?: string;
  features?: string[];
}

export interface AnnualMatrixPricingProps {
  tiers?: AnnualMatrixPricingTier[];
  className?: string;
  onSelect?: (tier: AnnualMatrixPricingTier) => void;
}

const DEFAULTS: AnnualMatrixPricingTier[] = [
  {
    name: "Developer",
    price: "$19",
    period: "/mo",
    cta: "Select tier",
    features: ["Unlimited components", "Theme studio", "Community support"],
  },
  {
    name: "Enterprise",
    price: "$49",
    period: "/mo",
    highlight: true,
    cta: "Deploy now",
    features: ["Everything in Developer", "SLA + audit logs", "Priority support"],
  },
];

/**
 * AnnualMatrixPricing — two-tier pricing matrix with an accent on the
 * recommended plan. Renders semantic <ul> for features and a real
 * <button> per tier so it works with screen readers and keyboards.
 */
export function AnnualMatrixPricing({
  tiers = DEFAULTS,
  className,
  onSelect,
}: AnnualMatrixPricingProps) {
  return (
    <div
      className={[
        "grid grid-cols-1 sm:grid-cols-2 gap-4 w-full max-w-3xl",
        className,
      ]
        .filter(Boolean)
        .join(" ")}
    >
      {tiers.map((tier) => (
        <div
          key={tier.name}
          className={[
            "p-5 rounded-2xl border bg-card flex flex-col gap-3",
            tier.highlight
              ? "border-primary shadow-lg shadow-primary/10"
              : "border-border",
          ].join(" ")}
        >
          <span
            className={[
              "text-[10px] font-bold uppercase tracking-[0.16em]",
              tier.highlight ? "text-primary" : "text-muted-foreground",
            ].join(" ")}
          >
            {tier.name}
          </span>
          <div className="flex items-baseline gap-1">
            <span className="text-3xl font-black text-foreground">
              {tier.price}
            </span>
            <span className="text-xs text-muted-foreground">
              {tier.period ?? ""}
            </span>
          </div>
          {tier.features && tier.features.length > 0 ? (
            <ul className="space-y-1.5 text-xs text-muted-foreground">
              {tier.features.map((f) => (
                <li key={f} className="flex items-start gap-2">
                  <span
                    aria-hidden
                    className="mt-1.5 h-1.5 w-1.5 rounded-full bg-primary"
                  />
                  <span>{f}</span>
                </li>
              ))}
            </ul>
          ) : null}
          <button
            type="button"
            onClick={() => onSelect?.(tier)}
            className={[
              "mt-auto inline-flex items-center justify-center px-4 py-2 rounded-lg text-xs font-semibold transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/60",
              tier.highlight
                ? "bg-primary text-primary-foreground hover:brightness-110"
                : "bg-secondary text-foreground border border-border hover:bg-secondary/80",
            ].join(" ")}
          >
            {tier.cta ?? "Choose plan"}
          </button>
        </div>
      ))}
    </div>
  );
}

export default AnnualMatrixPricing;
